  prev: 'Coup précédent {m} : {q}', prevBest: 'Un coup « {c} » : le même que le premier choix de l’IA.', prevAlt: 'Le premier choix de l’IA était {m} ({c}).', prevAltOk: 'Presque aussi bon que le premier choix de l’IA, {m} ({c}).',
