    mob: { m: ['可下位置', '行動力'], t: '可下位置（行動力）', d: '輪到的一方能下的格數。變少時會被迫下在 X 或 C 等不想下的地方。' },
    joseki: { m: ['定石'], t: '定石', d: '序盤的固定手順。經過長期研究、容易保持均勢的下法，並有名稱（虎、兔、牛等）。' },
